head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > tooltip]<br/>MultiSelect 컴포넌트 영역으로 마우스가 들어왔을 때 표시할 툴팁을 설정합니다.",
    "validation" : [
        "tooltip 속성에 설정한 텍스트(String)가 툴팁에 표시됩니다.",
        "tooltip 속성을 설정하지 않으면 툴팁이 표시되지 않습니다.",
        "tooltip 속성을 설정하지 않으면 tooltipLocaleRef 속성은 무시됩니다.",
        "tooltip, useLocale, tooltipLocaleRef 속성을 모두 설정하면 클라이언트 다국어가 적용되고 tooltip 속성값은 무시됩니다.",
        "툴팁은 MultiSelect 컴포넌트의 좌상단과 툴팁의 좌하단 위치가 일치하도록 표시되며 해당 위치가 기본 위치가 됩니다.",
        // "MultiSelect 컴포넌트가 화면 상단에 위치하여 툴팁이 표시될 공간이 없는 경우 컴포넌트의 좌하단에 표시됩니다.",
        "부모 컴포넌트에 tooltip 속성이 설정되어 있고 MultiSelect 컴포넌트에 tooltip 속성값이 있으면 tooltip 속성과 툴팁 관련 속성이 부모 컴포넌트에 반영(빈값 포함)됩니다.",
        "부모 컴포넌트에 tooltip 속성이 설정되어 있고 MultiSelect 컴포넌트에 tooltip 속성값이 없으면 툴팁 관련 일부 속성만 부모 컴포넌트에 반영(빈값 포함)됩니다.",
        "툴팁의 디자인과 관련된 설정은 CSS 에서 조정 가능합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// target1 클릭 시 tooltip 풍선 정보 출력
// (Playwright 가 target1 hover → tooltip 풍선 표시 → 클릭 → 결과 출력)
// 기대 동작: tooltip 속성에 설정한 텍스트가 풍선에 표시되고 display 가 visible 상태
scwin.target1_onclick = function (e) {
    $c.gcm.getTooltipInfo(wf_body_bottom);

    // 풍선 라벨 innerHTML 직접 출력 (디자인/CSS 검증용)
    var balloonLabel = document.querySelector('.w2balloonTip_label');
    if (balloonLabel) {
        wf_body_bottom.getObj("scwin").setReturnValue("target1 .w2balloonTip_label innerHTML : " + balloonLabel.innerHTML);
    }
};



// target2 클릭 시 tooltip 풍선 정보 출력
// 기대 동작: tooltip 속성 미설정 → 풍선 DOM 미생성(또는 textContent 가 비어있음)
scwin.target2_onclick = function (e) {
    var balloon = document.querySelector('.w2balloonTip');
    var balloonLabel = document.querySelector('.w2balloonTip_label');
    if (balloon) {
        wf_body_bottom.getObj("scwin").setReturnValue("target2 .w2balloonTip display : " + balloon.style.display);
        wf_body_bottom.getObj("scwin").setReturnValue("target2 .w2balloonTip_label textContent : " + (balloonLabel ? balloonLabel.textContent : "(no label)"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("target2 .w2balloonTip : (none) - tooltip 미설정으로 풍선 미생성");
    }
};



// target3 (tooltipLocaleRef 만 설정, tooltip 미설정) 클릭 시 정보 출력
// 기대 동작: tooltip 미설정이므로 tooltipLocaleRef 무시 → 풍선 미생성
scwin.target3_onclick = function (e) {
    var balloon = document.querySelector('.w2balloonTip');
    var balloonLabel = document.querySelector('.w2balloonTip_label');
    if (balloon) {
        wf_body_bottom.getObj("scwin").setReturnValue("target3 .w2balloonTip display : " + balloon.style.display);
        wf_body_bottom.getObj("scwin").setReturnValue("target3 .w2balloonTip_label textContent : " + (balloonLabel ? balloonLabel.textContent : "(no label)"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("target3 .w2balloonTip : (none) - tooltip 미설정으로 tooltipLocaleRef 무시됨");
    }
};



// target4 (tooltip + useLocale + tooltipLocaleRef 모두 설정) 클릭 시 정보 출력
// 기대 동작: 클라이언트 다국어 적용, tooltipLocaleRef 의 Key 가 다국어 처리됨
//          (langpack 미정의 시 'global_undefined' 가 적용되어 tooltip 속성값이 무시됨)
scwin.target4_onclick = function (e) {
    $c.gcm.getTooltipInfo(wf_body_bottom);
};



// target5 (부모 그룹에 tooltip + 자식 multiselect 에 tooltip) 클릭 시 정보 출력
// 기대 동작: 자식의 tooltip 속성이 부모 그룹에 반영되어 풍선이 자식의 tooltip 텍스트로 표시됨
scwin.target5_onclick = function (e) {
    $c.gcm.getTooltipInfo(wf_body_bottom);
};



// target6 (부모 그룹에 tooltip + 자식 multiselect 에 tooltip 미설정) 클릭 시 정보 출력
// 기대 동작: 자식에 tooltip 미설정이므로 일부 속성만 부모에 반영, 부모의 tooltip 텍스트가 풍선에 표시됨
scwin.target6_onclick = function (e) {
    $c.gcm.getTooltipInfo(wf_body_bottom);
};
